#!/usr/bin/env python3
"""Decode the base64 bitcoin.py backup file"""

import base64

# The base64 encoded content from _bitcoin.py.bak
e = b''

# Decode the base64 string
decoded = base64.b64decode(e).decode('utf-8')

# Save to file
with open('bitcoin_decoded.py', 'w', encoding='utf-8') as f:
    f.write(decoded)

print("✓ Decoded successfully!")
print(f"✓ Saved to: bitcoin_decoded.py")
print(f"✓ File size: {len(decoded)} bytes")
